<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Powiadomienia';$data=$notificationsPage;$items=$data['items'];
$labels=['mention'=>'Wzmianka','comment.reply'=>'Odpowiedź na komentarz','comment.created'=>'Nowy komentarz','page.updated'=>'Zmieniono obserwowaną stronę','page.created'=>'Nowa strona w obserwowanej przestrzeni','page.shared'=>'Udostępniono stronę','task.assigned'=>'Przypisano zadanie']; ?>
<div class="page-head"><div><p class="eyebrow">Centrum powiadomień</p><h1>Powiadomienia</h1></div><form method="post" action="<?=Html::e(Url::to('/notifications/read-all'))?>"><?=Csrf::field()?><button class="button secondary">Oznacz wszystkie jako przeczytane</button></form></div>
<section class="card"><?php if(!$items):?><div class="empty-state"><h2>Brak powiadomień</h2><p class="muted">Nowe wzmianki, odpowiedzi, obserwowane strony i zadania pojawią się tutaj.</p></div><?php endif;?>
<?php foreach($items as $n):$label=$labels[$n['type']]??$n['type'];$actor=trim((string)($n['actor_name']??''))?:($n['actor_username']??'System');?><div class="notification-row <?=$n['read_at']===null?'unread':''?>"><div><strong><?=Html::e($label)?></strong><p><?=Html::e($actor)?><?php if(!empty($n['payload']['title'])):?> · <?=Html::e($n['payload']['title'])?><?php endif;?></p><small><?=Html::e($n['created_at'])?></small></div><div class="actions"><?php if($n['url']):?><a class="button secondary" href="<?=Html::e(Url::to((string)$n['url']))?>">Otwórz</a><?php endif;?><?php if($n['read_at']===null):?><form method="post" action="<?=Html::e(Url::to('/notifications/'.$n['id'].'/read'))?>"><?=Csrf::field()?><input type="hidden" name="return" value="/notifications?page=<?=Html::e($data['page'])?>"><button class="link-button">Oznacz jako przeczytane</button></form><?php endif;?></div></div><?php endforeach;?>
<?php if($data['has_previous']||$data['has_next']):?><div class="pager"><?php if($data['has_previous']):?><a class="button secondary" href="<?=Html::e(Url::to('/notifications?page='.($data['page']-1)))?>">Poprzednia</a><?php else:?><span></span><?php endif;?><span>Strona <?=Html::e($data['page'])?></span><?php if($data['has_next']):?><a class="button secondary" href="<?=Html::e(Url::to('/notifications?page='.($data['page']+1)))?>">Następna</a><?php endif;?></div><?php endif;?></section>
